head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil40200";
scwin.confirm = null;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_pageBody = async function () {
    try {
        const agent = navigator.userAgent.toLowerCase();
        if (!(navigator.appName === "Netscape" && navigator.userAgent.search("Trident") !== -1) || (agent.indexOf("msie") !== -1)) {
            if (await $c.win.confirm("제출시스템(filing.krx.co.kr)을 이용하시려면\nIEMODE를 설치/설정 하셔야 합니다.\n설치페이지로 이동하시겠습니까?")) {
                await scwin.announcementView();
            } else {
                history.back();
            }
        }
        scwin.initValue();

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil40200.onpageload' }); }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.confirm = confirm;
        await scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil40200.onpageload' });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
