///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_AnnouncementView
 * @description Announcement View 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_AnnouncementView = async function () {
    const sbmOptions = {
        id: "tx_fn_AnnouncementView",
        method: "post",
        action: "/outer/announcement.do",
        ref: "dma_AnnouncementViewReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_Confirm
 * @description Confirm 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_Confirm = async function () {
    const sbmOptions = {
        id: "tx_fn_Confirm",
        method: "post",
        action: "/outer/register.do",
        ref: "dma_ConfirmReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name announcementView
 * @description announcement View 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.announcementView = async function () {
    const frm = (document.applyCheck || { elements: [] });
    $c.util.getComponent('dma_AnnouncementViewReq').set('method', 'searchAnnouncementDetail');
    $c.util.getComponent('dma_AnnouncementViewReq').set('contnId', '10004');
    frm.action = '/outer/announcement.do';
    await scwin.tx_fn_AnnouncementView();
};

async function confirm() {
    const frm = (document.applyCheck || { elements: [] });
    if (!$c.cm.fn_IsChecked($c.util.getComponent('rd_corpUsrTpCd'))) {
        await $c.win.alert('회원 분류를 선택하세요');
        return;
    }
    if (frm.isurCd) {
        if (frm.isurCd.value.length !== 5) {
            await $c.win.alert('회사코드는 반드시 5자리를 입력하셔야 합니다');
            return;
        }
        $c.util.getComponent('dma_AnnouncementViewReq').set('uniqueCode', frm.isurCd.value);
    }
    if (frm.mbrNo) {
        $c.util.getComponent('dma_AnnouncementViewReq').set('uniqueCode', frm.mbrNo.value);
    }
    if (await scwin.checkRequired(frm.uniqueCode)) {
        return;
    }
    if ($c.util.fieldEl('dma_ConfirmReq', 'corpUsrNm')) {
        if (await scwin.checkRequired($c.util.getComponent('dma_ConfirmReq'))) {
            return;
        }
        if (await (async (c) => { const v = String((c && c.getValue) ? (c.getValue() ?? "") : ""); const max = Number((c && c.getUserData) ? ((c.getUserData("maxByteLength") || c.getUserData("maxLength")) ?? 0) : 0) || 0; if (max && $c.str.getByteLength(v) > max) { const lbl = ""; await $c.win.alert((lbl ? ("'" + lbl + "' 항목은 ") : "") + "한글 " + (max / 2) + "자, 영문 " + max + "자까지 가능합니다."); return true; } return false; })($c.util.getComponent('dma_ConfirmReq'))) {
            return;
        }
        $c.util.getComponent('dma_ConfirmReq').set('corpUsrNm', $c.cm.fn_IgnoreSpaces($c.util.getComponent('dma_ConfirmReq').get('corpUsrNm')));
    }
    $c.util.getComponent('dma_AnnouncementViewReq').set('method', 'registerApplyForm');
    frm.action = '/outer/register.do';
    await scwin.tx_fn_Confirm();
}

/**
 * @method
 * @name changeUsrTpCd
 * @description change Usr Tp Cd 처리
 * @param {*} _obj _obj
 * @returns {void}
 * @hidden N
 */
scwin.changeUsrTpCd = function (_obj) {
    const usrTpCd = _obj.getValue();
    if (usrTpCd === '14') {
        (($c.util.getComponent("txt_isurCdDiv")) && ($c.util.getComponent("txt_isurCdDiv")).setValue ? ($c.util.getComponent("txt_isurCdDiv")).setValue(scwin.getIsurCdTitle('2')) : (($c.util.getComponent("txt_isurCdDiv")) ? (($c.util.getComponent("txt_isurCdDiv")).innerHTML = scwin.getIsurCdTitle('2')) : void (scwin.getIsurCdTitle('2'))));
    } else {
        if (usrTpCd === '22') {
            (($c.util.getComponent("txt_isurCdDiv")) && ($c.util.getComponent("txt_isurCdDiv")).setValue ? ($c.util.getComponent("txt_isurCdDiv")).setValue(scwin.getIsurCdTitle('3')) : (($c.util.getComponent("txt_isurCdDiv")) ? (($c.util.getComponent("txt_isurCdDiv")).innerHTML = scwin.getIsurCdTitle('3')) : void (scwin.getIsurCdTitle('3'))));
        } else {
            if (usrTpCd === '15' || usrTpCd === '23') {
                (($c.util.getComponent("txt_isurCdDiv")) && ($c.util.getComponent("txt_isurCdDiv")).setValue ? ($c.util.getComponent("txt_isurCdDiv")).setValue(scwin.getIsurCdTitle('4')) : (($c.util.getComponent("txt_isurCdDiv")) ? (($c.util.getComponent("txt_isurCdDiv")).innerHTML = scwin.getIsurCdTitle('4')) : void (scwin.getIsurCdTitle('4'))));
            } else {
                (($c.util.getComponent("txt_isurCdDiv")) && ($c.util.getComponent("txt_isurCdDiv")).setValue ? ($c.util.getComponent("txt_isurCdDiv")).setValue(scwin.getIsurCdTitle('1')) : (($c.util.getComponent("txt_isurCdDiv")) ? (($c.util.getComponent("txt_isurCdDiv")).innerHTML = scwin.getIsurCdTitle('1')) : void (scwin.getIsurCdTitle('1'))));
            }
        }
    }
};

/**
 * @method
 * @name goURL
 * @description go URL 처리
 * @param {*} _target _target
 * @returns {void}
 * @hidden N
 */
scwin.goURL = function (_target) {
    let linkUrl;
    if (_target === 'registerInfo') {
        linkUrl = '/outer/register.do?method=registerInfo';
    } else {
        if (_target === 'faq') {
            linkUrl = '/outer/faq.do?method=searchFAQ&faqBzTpCd=5';
        }
    }
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — "
    $c.win.setPageFrameSrc($c.win.getFrame(), (function (__u) { const __s = String(__u == null ? "" : __u); if (!/\.xml(\?|#|$)/.test(__s)) { throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + __s, unresolved: "nav:" + __s }; } return __u; })(linkUrl));
};

/**
 * @method
 * @name initValue
 * @description init Value 처리
 * @returns {void}
 * @hidden N
 */
scwin.initValue = function () {
    $c.util.getComponent('dma_ConfirmReq').reset();
    (($c.util.getComponent("txt_isurCdDiv")) && ($c.util.getComponent("txt_isurCdDiv")).setValue ? ($c.util.getComponent("txt_isurCdDiv")).setValue(scwin.getIsurCdTitle('1')) : (($c.util.getComponent("txt_isurCdDiv")) ? (($c.util.getComponent("txt_isurCdDiv")).innerHTML = scwin.getIsurCdTitle('1')) : void (scwin.getIsurCdTitle('1'))));
};

/**
 * @method
 * @name getIsurCdTitle
 * @description get Isur Cd Title 처리
 * @param {*} _type _type
 * @returns {void}
 * @hidden N
 */
scwin.getIsurCdTitle = function (_type) {
    let isurCdTitle;
    let explan;
    let inputBox;
    if (_type === '1') {
        explan = "※ 회사코드(5자리)란?<br/>" + "종목코드 6자리 중 마지막 1자리를 제외한 5자리 코드이며, 표준코드시스템에서 부여한 ‘기관코드’입니다.<br/>" + "표준코드 신청/조회 : 표준코드시스템 (<a href='http://isin.krx.co.kr' target='_blank'>http://isin.krx.co.kr</a>)<br/>";
        +"표준코드시스템 또는 금융감독원 DART 제출시스템에서 변경된 정보는 익일에 KRX 상장공시제출시스템에 반영됩니다.";
        inputBox = "<table width='50%'>" + "<tr><td align='right'>회사코드(5자리) : </td>" + "<td><input type='text' name='isurCd' class='form_search' size='10' maxLength='5' style='margin:0 5 0 5;' /></td>" + "<td align='right'><a href='#' class='btn_w_gra' onclick='confirm();''>확인</a></td></tr>" + "</table>";
    } else {
        if (_type === '2') {
            explan = "※ 대상회사코드(5자리)란?<br/>" + "사무관리/수탁 대상 회사의 종목코드 6자리 중 마지막 1자리를 제외한 5자리 코드이며, 표준코드시스템에서 부여한 ‘기관코드’입니다.<br/>" + "표준코드 신청/조회 : 표준코드시스템 (<a href='http://isin.krx.co.kr' target='_blank'>http://isin.krx.co.kr</a>)<br/>";
            +"표준코드시스템 또는 금융감독원 DART 제출시스템에서 변경된 정보는 익일에 KRX 상장공시제출시스템에 반영됩니다.";
            inputBox = "<table width='50%'>" + "<tr><td align='right'>대상회사코드(5자리) : </td><td><input type='text' name='isurCd' class='form_search' size='10' maxLength='5' style='margin:0 5 0 5;' /></td>" + "<td align='right' rowspan='2'><a href='#' class='btn_w_gra' onclick='confirm();''>확인</a></td></tr>" + "<tr><td align='right'>사용자 이름 : </td><td><input type='text' name='corpUsrNm' alt='사용자 이름' maxLength='80' class='form_search' size='10' style='margin:0 5 0 5;'/></td></tr>" + "</table>";
        } else {
            if (_type === '3') {
                explan = "※ 회원고유코드란?<br/>" + "회원사를 구분하는 5자리 코드입니다.<br/>";
                +"(코스닥)상장 주간사 의 회원고유코드는 회원업무시스템(http://member.krx.co.kr)에서 안내합니다.";
                inputBox = "<table width='50%'>" + "<tr><td align='right'>회원고유코드 : </td><td><input type='text' name='mbrNo' class='form_search' size='10' maxLength='5' style='margin:0 5 0 5;' /></td>" + "<td align='right'><a href='#' class='btn_w_gra' onclick='confirm();''>확인</a></td></tr>" + "</table>";
            } else {
                if (_type === '4') {
                    explan = "※ 회사코드(5자리)란?<br/>" + "종목코드 6자리 중 마지막 1자리를 제외한 5자리 코드이며, 표준코드시스템에서 부여한 ‘기관코드’입니다.<br/>" + "표준코드 신청/조회 : 표준코드시스템 (<a href='http://isin.krx.co.kr' target='_blank'>http://isin.krx.co.kr</a>)<br/>";
                    +"표준코드시스템 또는 금융감독원 DART 제출시스템에서 변경된 정보는 익일에 KRX 상장공시제출시스템에 반영됩니다.";
                    inputBox = "<table width='50%'>" + "<tr><td align='right'>회사코드(5자리) : </td><td><input type='text' name='isurCd' class='form_search' size='10' maxLength='5' style='margin:0 5 0 5;' /></td>" + "<td align='right' rowspan='2'><a href='#' class='btn_w_gra' onclick='confirm();''>확인</a></td></tr>" + "<tr><td align='right'>사용자 이름 : </td><td><input type='text' name='corpUsrNm' alt='사용자 이름' maxLength='80' class='form_search' size='10' style='margin:0 5 0 5;'/></td></tr>" + "</table>";
                } else {
                    if (_type === '5') {
                        explan = "";
                        inputBox = "<table width='50%'>" + "<tr><td align='right'></td><td></td>" + "<td align='right' rowspan='2'><img src='/img/btn/btn_ok.gif' onclick='confirm();' style='cursor:hand'/></td></tr>" + "<tr><td align='right'></td><td></td></tr>" + "</table>";
                    }
                }
            }
        }
    }
    isurCdTitle = "<table width='100%'>" + "<tr><td class='join_title'><img src='/img/title/join_3_5.gif'/></td></tr>" + "<tr><td style='font-size:11px;' class='ex'>" + explan + "</td></tr>" + "<tr style='height:5px;'><td></td></tr>" + "<tr><td style='padding:10 0 10 20;'>" + inputBox + "</td></tr></table>";
    return isurCdTitle;
};

/**
 * @method
 * @name checkRequired
 * @description 필수 입력 검사 — 값이 비면 항목명으로 알리고 포커스를 준 뒤 true(as-is fn_NullChk 의미 보존 · pcc/fil 반입 후보)
 * @param {Object} comp 입력 컴포넌트
 * @returns {Promise<Boolean>} 비어 있으면 true
 * @hidden N
 */
scwin.checkRequired = async function (comp) {
    if (!comp || !$c.util.isEmpty($c.str.trim(String(comp.getValue() ?? "")))) { return false; }
    const name = (typeof comp.getTitle === "function" && comp.getTitle()) || comp.getID();
    await $c.win.alert("'" + name + "' 항목을 입력하세요");
    comp.focus();
    return true;
};
